#include <iostream>
#include <vector>
struct MyData {
  std::vector<int> data;
  MyData(const std::vector<int>& d) : data(d) {}
};
MyData createData() {
  std::vector<int> v = {1, 2, 3, 4, 5};
  return MyData(v);
}
int main() {
  MyData md = createData();
  for (int i : md.data) std::cout << i << " ";
  std::cout << std::endl;
  return 0;
}
